window.MOTIF_CATALOG_CHUNKS[23]={"cards":[{"id":"ML-T02348","row_version":2,"title":"매체 전환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02346","tag_path":[],"summary":"매체 전환은 관습이나 내용을 책·영상·게임·공연 등 다른 표현 매체의 형식으로 옮기는 방식이다. 장르나 시대가 바뀐 것과 구별해, 매체 고유의 표현 수단과 제약이 어떻게 반영됐는지 본다.","accent":"#93856B","tab":"#7D8FA3","facet":"변주·관습","bookmark":"매체 전환","entry_url":"cards/ML-T02348/index.html"},{"id":"ML-T02349","row_version":3,"title":"시대 전환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02346","tag_path":[],"summary":"시대 전환은 관습의 배경이나 표현을 다른 시대의 조건에 맞춰 옮기는 방식이다. 시대 분위기만 바꾼 경우와 달리, 기술·규범·생활 조건이 관습의 기능이나 의미를 어떻게 바꾸는지 확인한다.","accent":"#93856B","tab":"#7D8FA3","facet":"변주·관습","bookmark":"시대 전환","entry_url":"cards/ML-T02349/index.html"},{"id":"ML-T02350","row_version":3,"title":"문화권 전환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02346","tag_path":[],"summary":"문화권 전환은 관습을 다른 문화권의 가치·상징·사회적 맥락에 맞게 옮기거나 조정하는 방식이다. 표면적 명칭 변경만으로 판단하지 말고, 의미와 기능이 새 맥락에서 어떻게 달라지는지 살핀다.","accent":"#93856B","tab":"#7D8FA3","facet":"변주·관습","bookmark":"문화권 전환","entry_url":"cards/ML-T02350/index.html"},{"id":"ML-T02351","row_version":3,"title":"대상층 전환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02346","tag_path":[],"summary":"대상층 전환은 관습의 표현과 전제를 다른 연령·경험·관심 집단이 이해하고 받아들이도록 조정하는 방식이다. 홍보상 표적만 바뀐 경우와 구별해, 실제 내용과 표현이 대상층에 맞게 달라졌는지 확인한다.","accent":"#93856B","tab":"#7D8FA3","facet":"변주·관습","bookmark":"대상층 전환","entry_url":"cards/ML-T02351/index.html"},{"id":"ML-T02352","row_version":3,"title":"관습 판단","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"group","parent_id":"ML-F28","tag_path":[],"summary":"관습 판단은 작품이 관습을 어떤 익숙함과 평가의 맥락에서 사용하는지 따지는 일이다. 관습의 존재 자체와 수용자의 반응을 구별하고, 판단 시점과 대상 집단을 분명히 한다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"관습 판단","entry_url":"cards/ML-T02352/index.html"},{"id":"ML-T02353","row_version":4,"title":"익숙한 관습으로 사용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02352","tag_path":[],"summary":"익숙한 관습으로 사용은 해당 맥락의 관객이나 플레이어가 이미 알고 있을 법한 관습을 특별한 강조 없이 활용하는 방식이다. 널리 쓰인다는 판단은 장르·시기·대상층을 고려해 적용하고, 필수 관습과 동일시하지 않는다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"익숙한 관습으로 사용","entry_url":"cards/ML-T02353/index.html"},{"id":"ML-T02354","row_version":3,"title":"장르 필수 관습으로 사용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02352","tag_path":[],"summary":"장르 필수 관습으로 사용은 특정 장르의 정체성이나 기본 작동에 핵심적이라고 여겨지는 관습을 갖춰 사용하는 방식이다. 흔하다는 이유만으로 필수라 부르지 말고, 그 관습이 빠질 때 장르의 성립이나 기대가 달라지는지 따진다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"장르 필수 관습으로 사용","entry_url":"cards/ML-T02354/index.html"},{"id":"ML-T02355","row_version":3,"title":"상투적으로 수용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02352","tag_path":[],"summary":"상투적으로 수용은 관습이 익숙한 방식으로 되풀이되어 새로움이나 개별적 의미가 약하게 받아들여지는 상태를 가리킨다. 작품의 사용 방식과 수용자의 평가를 나눠 보고, 반복 여부만으로 상투적이라고 단정하지 않는다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"상투적으로 수용","entry_url":"cards/ML-T02355/index.html"},{"id":"ML-T02356","row_version":3,"title":"신선하게 변주","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02352","tag_path":[],"summary":"신선하게 변주는 익숙한 관습을 알아볼 수 있게 유지하면서 구성·맥락·기능을 바꾸어 새로운 효과를 내는 방식이다. 단순한 낯섦이나 새로운 소재의 추가와 구별해, 기존 관습과 변형 사이의 관계를 짚는다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"신선하게 변주","entry_url":"cards/ML-T02356/index.html"},{"id":"ML-T02357","row_version":3,"title":"의도적 진부함","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02352","tag_path":[],"summary":"의도적 진부함은 이미 낡았다고 여겨지는 관습을 그 진부함이 드러나도록 일부러 사용해 효과를 만드는 방식이다. 우연히 상투적인 결과가 나온 경우와 구별해, 작품이 진부함을 인식하고 활용한다는 단서를 확인한다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"의도적 진부함","entry_url":"cards/ML-T02357/index.html"},{"id":"ML-T02358","row_version":2,"title":"시대에 따른 평가 변화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":"tag","parent_id":"ML-T02352","tag_path":[],"summary":"시대에 따른 평가 변화는 같은 관습이나 작품의 쓰임이 시대별 규범·기대·비평 기준에 따라 다르게 받아들여지는 현상이다. 현재의 반응만으로 과거 평가를 추정하지 말고, 비교하는 시기와 평가 맥락을 구체적으로 구분한다.","accent":"#93856B","tab":"#A07A87","facet":"변주·관습","bookmark":"시대에 따른 평가 변화","entry_url":"cards/ML-T02358/index.html"},{"id":"ML-T02359","row_version":2,"title":"자료 계열","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"서사나 이미지가 만들어질 때 재료가 된 이야기 전승, 기록, 작품, 관찰의 출처 유형을 가리킨다. 작품을 분류할 때는 실제로 차용·변형한 자료의 성격을 기준으로 삼고, 단순한 주제 유사성만으로 계보를 단정하지 않는다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"자료 계열","entry_url":"cards/ML-T02359/index.html"},{"id":"ML-T02360","row_version":3,"title":"신화 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"신과 초자연적 존재, 세계의 기원, 의례와 공동체의 질서를 설명하는 신앙적 이야기에서 모티프를 이어받는 방식이다. 신성한 존재나 창세가 나온다는 이유만으로 붙이지 말고, 해당 이야기가 신화적 기능과 전승 맥락을 실제로 활용하는지 본다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"신화 계보","entry_url":"cards/ML-T02360/index.html"},{"id":"ML-T02361","row_version":2,"title":"전설 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"특정 인물이나 장소, 사건을 중심으로 역사적 기억과 초자연적 요소가 결합해 전해지는 이야기에서 소재를 가져온다. 기록된 사실과 전승 속 변형을 구분하고, 허구적 모험담이라는 이유만으로 전설 계보로 보지 않는다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"전설 계보","entry_url":"cards/ML-T02361/index.html"},{"id":"ML-T02362","row_version":4,"title":"민담 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"익명의 화자와 유동적인 판본을 통해 구전된 이야기 유형이나 줄거리 관습을 바탕으로 삼는다. 반복되는 서사 구조나 전승 모티프의 사용을 확인하고, 특정 작가의 창작 동화와 구별한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"민담 계보","entry_url":"cards/ML-T02362/index.html"},{"id":"ML-T02363","row_version":2,"title":"우화 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"동물이나 의인화된 존재의 간결한 사건을 통해 교훈이나 세태 풍자를 전달하는 이야기 전통을 활용한다. 교훈적 결말만으로 판단하지 말고, 우화의 압축된 구성과 비유적 기능이 작품에서 작동하는지 살핀다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"우화 계보","entry_url":"cards/ML-T02363/index.html"},{"id":"ML-T02364","row_version":4,"title":"종교 서사 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"종교 공동체의 경전·주석·성인전 등에 담긴 인물과 사건, 구원이나 수행의 서사에서 재료를 얻는다. 종교적 표식이나 분위기만 빌린 경우와 구체적인 종교 서사 전통을 참조한 경우를 구별한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"종교 서사 계보","entry_url":"cards/ML-T02364/index.html"},{"id":"ML-T02365","row_version":3,"title":"역사 기록 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"연대기, 문서, 증언, 유물 등 과거에 관한 기록이나 그 기록의 해석을 서사 재료로 삼는다. 역사적 시대 배경만 있는 작품이 아니라 기록된 사건·인물·정황을 실제로 활용하는지 기준으로 판단한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"역사 기록 계보","entry_url":"cards/ML-T02365/index.html"},{"id":"ML-T02366","row_version":2,"title":"문학 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"시·소설·희곡 등 기존 문학 작품의 인물, 장면, 문체, 구성 원리를 이어받거나 변주한다. 문학적 분위기의 막연한 유사성보다 식별 가능한 작품이나 문학 전통과의 관계를 확인한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"문학 계보","entry_url":"cards/ML-T02366/index.html"},{"id":"ML-T02367","row_version":3,"title":"대중문화 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"영화, 만화, 게임, 방송 등 대중적으로 유통된 매체 작품이나 관습에서 표현과 서사 재료를 가져온다. 널리 알려진 소재라는 이유만으로 분류하지 말고, 대중문화 작품 또는 형식과의 구체적 연결을 살핀다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"대중문화 계보","entry_url":"cards/ML-T02367/index.html"},{"id":"ML-T02368","row_version":3,"title":"현실 관찰 계보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02359","tag_path":[],"summary":"일상생활, 사회관계, 자연현상처럼 관찰 가능한 현실의 패턴을 포착해 서사나 표현으로 옮긴다. 현실적인 묘사만으로 붙이지 말고, 특정한 경험이나 행동 양식의 관찰이 작품의 모티프 형성에 기여했는지 본다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"현실 관찰 계보","entry_url":"cards/ML-T02368/index.html"},{"id":"ML-T02369","row_version":3,"title":"동아시아 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"동아시아 여러 사회에서 전승된 신화·설화·의례 서사와 문화적 변형을 포괄한다. 넓은 지역 범주만으로 세부 계보를 확정하지 말고, 자료의 전승권과 작품이 활용한 구체적 전통을 함께 확인한다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"동아시아 전승","entry_url":"cards/ML-T02369/index.html"},{"id":"ML-T02370","row_version":4,"title":"한국 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02369","tag_path":[],"summary":"한반도에서 전해진 신화, 설화, 민속 서사와 그 지역적 변형을 바탕으로 삼는다. 한국어 사용이나 한국 배경만으로 분류하지 말고, 한국의 전승 자료 또는 그 변형이 작품에 실제로 작용하는지 판단한다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"한국 전승","entry_url":"cards/ML-T02370/index.html"},{"id":"ML-T02371","row_version":3,"title":"중국 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02369","tag_path":[],"summary":"중국의 신화·설화·민간 서사와 역사적으로 축적된 전승을 재료로 활용한다. 중국풍 배경이나 한자 문화권 요소만으로 판단하지 말고, 중국에서 형성·전승된 이야기 모티프와의 연결을 본다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"중국 전승","entry_url":"cards/ML-T02371/index.html"},{"id":"ML-T02372","row_version":4,"title":"일본 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02369","tag_path":[],"summary":"일본에서 전승된 신화와 설화, 민속 이야기의 인물·존재·서사 구조를 활용한다. 일본을 배경으로 하거나 일본 대중문화의 표현을 차용한 경우와 전승 서사를 참조한 경우를 구별한다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"일본 전승","entry_url":"cards/ML-T02372/index.html"},{"id":"ML-T02373","row_version":4,"title":"몽골 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02369","tag_path":[],"summary":"몽골 지역과 몽골계 공동체에서 전승된 신화·영웅담·구전 서사의 재료를 가리킨다. 초원이나 유목 생활을 묘사하는 데 그치지 않고, 몽골 전승의 이야기나 상징이 계보를 이루는지 확인한다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"몽골 전승","entry_url":"cards/ML-T02373/index.html"},{"id":"ML-T02374","row_version":2,"title":"티베트 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02369","tag_path":[],"summary":"티베트 지역의 구전 전승과 종교적·민속적 이야기 전통에서 소재를 가져온다. 불교 요소가 있다는 사실만으로 분류하지 말고, 티베트 지역에서 전승된 서사적 맥락이 구체적으로 드러나는지 본다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"티베트 전승","entry_url":"cards/ML-T02374/index.html"},{"id":"ML-T02375","row_version":4,"title":"남아시아·동남아시아 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"남아시아와 동남아시아의 여러 지역에서 형성된 신화·설화·민속 서사 전통을 포괄한다. 넓은 권역 안의 전승을 서로 같은 것으로 취급하지 말고, 작품과 연결되는 지역·공동체의 자료를 구체화한다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"남아시아·동남아시아 전승","entry_url":"cards/ML-T02375/index.html"},{"id":"ML-T02376","row_version":3,"title":"인도 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02375","tag_path":[],"summary":"인도 지역에서 전승된 신화, 서사시, 설화와 민속 이야기의 재료를 활용한다. 인도 종교의 보편적 개념을 언급하는 것과 인도 전승의 구체적인 인물·사건·서사 구조를 참조하는 것을 구별한다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"인도 전승","entry_url":"cards/ML-T02376/index.html"},{"id":"ML-T02377","row_version":2,"title":"스리랑카 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02375","tag_path":[],"summary":"스리랑카에서 전승된 지역 설화와 역사·종교적 이야기의 변형을 바탕으로 삼는다. 남아시아의 다른 전통이나 불교 일반의 소재와 혼동하지 말고, 스리랑카와 연결되는 전승 맥락을 확인한다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"스리랑카 전승","entry_url":"cards/ML-T02377/index.html"},{"id":"ML-T02378","row_version":3,"title":"태국 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02375","tag_path":[],"summary":"태국에서 전승된 신화·민담·민속 서사와 지역적 각색을 활용한다. 동남아시아 공통 모티프나 태국을 배경으로 한 설정만으로 판단하지 말고, 태국 전승의 특징이 작품에 반영되는지 본다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"태국 전승","entry_url":"cards/ML-T02378/index.html"},{"id":"ML-T02379","row_version":3,"title":"베트남 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02375","tag_path":[],"summary":"베트남에서 전해진 신화와 설화, 민속 이야기의 인물·사건·상징을 서사 재료로 삼는다. 중국 문화의 영향이나 베트남 배경만으로 분류하지 말고, 베트남에서 전승된 이야기와의 구체적 관계를 확인한다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"베트남 전승","entry_url":"cards/ML-T02379/index.html"},{"id":"ML-T02380","row_version":4,"title":"인도네시아 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02375","tag_path":[],"summary":"인도네시아 여러 섬과 공동체에서 전승된 신화·설화·구전 서사를 활용한다. 단일한 국가 전통으로 뭉뚱그리지 말고, 작품이 참조하는 섬·지역·공동체와 그 서사 자료를 식별한다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"인도네시아 전승","entry_url":"cards/ML-T02380/index.html"},{"id":"ML-T02381","row_version":3,"title":"필리핀 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02375","tag_path":[],"summary":"필리핀의 여러 공동체에서 전승된 창세 이야기와 민담, 영웅담 등에서 재료를 얻는다. 스페인 식민기나 현대 필리핀 문화의 요소만으로 판단하지 말고, 지역 전승의 이야기적 연결을 확인한다.","accent":"#7B876E","tab":"#8B739C","facet":"기원·전승·참조","bookmark":"필리핀 전승","entry_url":"cards/ML-T02381/index.html"},{"id":"ML-T02382","row_version":3,"title":"서아시아·지중해 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"서아시아와 지중해 주변에서 형성된 신화·설화·고대 서사 전통을 포괄한다. 넓은 역사·문화권을 단일 전승으로 간주하지 말고, 작품이 참조한 지역과 전승 계통을 구체적으로 살핀다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"서아시아·지중해 전승","entry_url":"cards/ML-T02382/index.html"},{"id":"ML-T02383","row_version":2,"title":"메소포타미아 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02382","tag_path":[],"summary":"메소포타미아의 고대 도시 문명에서 기록·전승된 신화와 서사시, 신들의 이야기를 활용한다. 고대 서아시아의 분위기만으로 분류하지 말고, 메소포타미아 자료나 그 서사적 변형과의 관계를 확인한다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"메소포타미아 전승","entry_url":"cards/ML-T02383/index.html"},{"id":"ML-T02384","row_version":3,"title":"이란 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02382","tag_path":[],"summary":"이란 지역의 고대·민속 전승과 서사 전통에서 인물, 사건, 상징을 가져온다. 페르시아풍 미장센이나 이란 역사 배경만으로 판단하지 말고, 이란 전승의 특정한 서사 재료가 쓰였는지 본다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"이란 전승","entry_url":"cards/ML-T02384/index.html"},{"id":"ML-T02385","row_version":3,"title":"이집트 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02382","tag_path":[],"summary":"고대 이집트에서 형성된 신화와 종교 의례, 왕권·사후세계에 관한 서사 전통을 활용한다. 피라미드나 미라 같은 이미지의 사용과 이집트 신화·의례 서사의 참조를 구별한다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"이집트 전승","entry_url":"cards/ML-T02385/index.html"},{"id":"ML-T02386","row_version":4,"title":"그리스 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02382","tag_path":[],"summary":"고대 그리스에서 전승된 신화와 영웅담, 비극적 서사 및 그 후대 변형을 재료로 삼는다. 고전적 분위기나 그리스식 이름만으로 분류하지 말고, 구체적인 그리스 전승의 인물·구조·모티프를 확인한다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"그리스 전승","entry_url":"cards/ML-T02386/index.html"},{"id":"ML-T02387","row_version":4,"title":"로마 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02382","tag_path":[],"summary":"고대 로마의 신화·전설과 건국 서사, 로마 사회에서 형성된 이야기 전통을 활용한다. 그리스 전승과 공유되거나 흡수된 요소는 로마에서의 수용·변형이 작품에 중요한지 살펴 구별한다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"로마 전승","entry_url":"cards/ML-T02387/index.html"},{"id":"ML-T02388","row_version":3,"title":"아라비아 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02382","tag_path":[],"summary":"아라비아 지역에서 전승된 민담과 시적·구전 서사, 지역적 신화 요소를 바탕으로 삼는다. 사막 배경이나 아랍어권 문화 표지만으로 판단하지 말고, 아라비아 전승의 구체적인 이야기 재료를 확인한다.","accent":"#7B876E","tab":"#A58A4E","facet":"기원·전승·참조","bookmark":"아라비아 전승","entry_url":"cards/ML-T02388/index.html"},{"id":"ML-T02389","row_version":3,"title":"유럽·기타 지역 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"유럽과 그 밖의 여러 지역에서 전승된 신화·설화·민속 서사를 넓게 포괄한다. 지역을 특정할 수 있는 전승은 해당 세부 갈래로 판단하고, 이 범주는 자료 계보가 넓거나 다른 하위 항목에 들지 않을 때 적용한다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"유럽·기타 지역 전승","entry_url":"cards/ML-T02389/index.html"},{"id":"ML-T02390","row_version":3,"title":"북유럽 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"북유럽 지역의 신화와 영웅담, 민간 설화에서 인물과 서사 구조를 가져온다. 바이킹 시대의 외양이나 북유럽 배경만으로 분류하지 말고, 북유럽 전승 자료와의 구체적 연계를 본다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"북유럽 전승","entry_url":"cards/ML-T02390/index.html"},{"id":"ML-T02391","row_version":4,"title":"켈트 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"켈트어권 공동체에 전해진 신화·영웅담·민담의 서사와 상징을 활용한다. 켈트풍 장식이나 아일랜드·웨일스 배경만으로 판단하지 말고, 켈트 전승의 이야기 계통이 드러나는지 확인한다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"켈트 전승","entry_url":"cards/ML-T02391/index.html"},{"id":"ML-T02392","row_version":4,"title":"슬라브 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"동유럽과 북유럽 일부 슬라브계 공동체에서 전승된 신화, 민담, 민속 신앙의 이야기를 바탕으로 삼는다. 슬라브권 배경이나 이름만으로 분류하지 말고, 해당 전승의 존재·사건·서사 관습을 활용하는지 본다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"슬라브 전승","entry_url":"cards/ML-T02392/index.html"},{"id":"ML-T02393","row_version":3,"title":"서아프리카 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"서아프리카 지역의 공동체에서 구전된 창세 이야기, 동물담, 영웅담과 그 변형을 활용한다. 아프리카 전반을 하나의 전통처럼 다루지 말고, 서아프리카 전승의 지역적·공동체적 맥락을 확인한다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"서아프리카 전승","entry_url":"cards/ML-T02393/index.html"},{"id":"ML-T02394","row_version":4,"title":"동아프리카 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"동아프리카 지역에서 전해진 신화와 설화, 공동체의 구전 서사에서 소재를 얻는다. 아프리카 일반의 표상이나 특정 국가의 역사만으로 분류하지 말고, 동아프리카 전승 자료가 작품에서 작동하는지 살핀다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"동아프리카 전승","entry_url":"cards/ML-T02394/index.html"},{"id":"ML-T02395","row_version":4,"title":"아메리카 선주민 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"아메리카 대륙의 선주민 공동체가 전승해 온 창세 신화, 설화, 의례 서사를 활용한다. 서로 다른 민족과 공동체의 전통을 단일화하지 말고, 참조하는 공동체와 이야기 맥락을 구체적으로 확인한다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"아메리카 선주민 전승","entry_url":"cards/ML-T02395/index.html"},{"id":"ML-T02396","row_version":4,"title":"오세아니아 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02389","tag_path":[],"summary":"오세아니아의 섬 지역과 선주민 공동체에서 전해진 신화·항해담·민속 서사를 바탕으로 삼는다. 태평양 섬의 배경만으로 붙이지 말고, 특정 공동체의 전승과 그 문화적 맥락이 반영되는지 본다.","accent":"#7B876E","tab":"#528982","facet":"기원·전승·참조","bookmark":"오세아니아 전승","entry_url":"cards/ML-T02396/index.html"},{"id":"ML-T02397","row_version":2,"title":"종교적 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"종교의 경전·교리·의례·성스러운 인물과 서사적 참조 관계를 맺는 경우를 가리킨다. 종교를 소재로 삼거나 종교적 분위기를 내는 것과 특정 종교 전통의 이야기를 참조하는 것을 구별한다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"종교적 참조","entry_url":"cards/ML-T02397/index.html"},{"id":"ML-T02398","row_version":3,"title":"불교 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"불교 경전과 설화, 부처·보살·수행자의 이야기 및 불교적 우주관에서 서사 재료를 가져온다. 불교 상징이나 윤회 개념의 단순한 사용만으로 판단하지 말고, 불교 서사 전통과의 연결을 살핀다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"불교 서사 참조","entry_url":"cards/ML-T02398/index.html"},{"id":"ML-T02399","row_version":3,"title":"기독교 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"성경과 기독교 전승의 인물·사건·비유·구원 서사를 작품에 끌어온다. 기독교적 상징이나 도덕관이 나타나는 것만으로는 부족하며, 어떤 서사나 해석 전통을 참조하는지 확인한다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"기독교 서사 참조","entry_url":"cards/ML-T02399/index.html"},{"id":"ML-T02400","row_version":2,"title":"유대교 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"히브리 성서와 유대교의 주석·전승에 담긴 인물과 사건, 해석의 이야기에서 소재를 얻는다. 기독교 성서 전통과 겹치는 자료는 작품이 유대교적 해석이나 전승 맥락을 활용하는지 기준으로 구별한다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"유대교 서사 참조","entry_url":"cards/ML-T02400/index.html"},{"id":"ML-T02401","row_version":3,"title":"이슬람 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"쿠란과 하디스, 이슬람권의 전승·주석 서사에 등장하는 인물과 사건을 활용한다. 아랍 문화나 이슬람 사회를 배경으로 삼는 것만으로 분류하지 말고, 이슬람 서사 자료와의 구체적 관계를 본다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"이슬람 서사 참조","entry_url":"cards/ML-T02401/index.html"},{"id":"ML-T02402","row_version":3,"title":"힌두교 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"힌두교의 경전과 서사시, 신과 화신·영웅의 이야기를 서사 재료로 삼는다. 인도 지역 전승 전반과 동일시하지 말고, 힌두교의 특정 서사나 신학적 이야기 구조가 활용되는지 판단한다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"힌두교 서사 참조","entry_url":"cards/ML-T02402/index.html"},{"id":"ML-T02403","row_version":3,"title":"도교 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"도교 경전과 신선·성현·수행에 관한 전승, 도교적 우주관의 이야기를 참조한다. 도가 사상이나 동양적 분위기의 일반적 차용과 도교 서사 전통의 활용을 구별한다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"도교 서사 참조","entry_url":"cards/ML-T02403/index.html"},{"id":"ML-T02404","row_version":3,"title":"무속 서사 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02397","tag_path":[],"summary":"한국 무속의 굿과 무가, 신령·무당·저승을 다루는 구전 서사에서 재료를 얻는다. 무당이나 영혼이 등장하는 것만으로 판단하지 말고, 무속 의례와 서사 전승의 논리가 작품에 반영되는지 살핀다.","accent":"#7B876E","tab":"#7D8FA3","facet":"기원·전승·참조","bookmark":"무속 서사 참조","entry_url":"cards/ML-T02404/index.html"},{"id":"ML-T02405","row_version":2,"title":"역사·문예 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"실제 역사 자료와 문학 작품, 문예 전통에 대한 참조를 함께 가리킨다. 과거의 분위기나 문학적 문체만으로 적용하지 말고, 사건·인물·작품 가운데 무엇을 재료로 삼았는지 구별한다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"역사·문예 참조","entry_url":"cards/ML-T02405/index.html"},{"id":"ML-T02406","row_version":3,"title":"실제 사건 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02405","tag_path":[],"summary":"실제로 발생한 사건의 경과, 참여자, 기록이나 사회적 기억을 서사 구성에 반영한다. 현실에서 벌어질 법한 사건이라는 설정과 실제 사건을 참조한 작품을 구분하고, 확인 가능한 사건 연결을 기준으로 삼는다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"실제 사건 참조","entry_url":"cards/ML-T02406/index.html"},{"id":"ML-T02407","row_version":2,"title":"역사 인물 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02405","tag_path":[],"summary":"실존했던 인물의 생애, 행적, 공적 이미지나 후대의 기억을 작품 재료로 활용한다. 이름이나 시대만 빌린 허구 인물과 실제 인물 참조를 구별하고, 인물의 실재와 작품에서의 변형을 함께 본다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"역사 인물 참조","entry_url":"cards/ML-T02407/index.html"},{"id":"ML-T02408","row_version":2,"title":"고전문학 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02405","tag_path":[],"summary":"고전으로 인정된 시·소설·희곡 등 문학 작품의 인물, 사건, 구절, 구조를 참조한다. 옛 시대를 배경으로 하거나 고전적인 문체를 쓰는 것만으로 분류하지 말고, 특정 고전 작품과의 연결을 확인한다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"고전문학 참조","entry_url":"cards/ML-T02408/index.html"},{"id":"ML-T02409","row_version":2,"title":"미술 작품 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02405","tag_path":[],"summary":"회화·조각·건축 등 시각예술의 구도, 도상, 양식이나 특정 작품을 알아볼 수 있게 끌어온다. 작품에 적용할 때는 시각적 유사성만으로 참조를 단정하지 말고, 식별 가능한 요소나 맥락이 있는지 살핀다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"미술 작품 참조","entry_url":"cards/ML-T02409/index.html"},{"id":"ML-T02410","row_version":2,"title":"음악 작품 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02405","tag_path":[],"summary":"기존 음악 작품의 선율, 리듬, 가사, 편곡이나 공연 양식을 새 작품에 끌어와 연관을 만든다. 작품에 적용할 때는 분위기가 비슷한 데 그치는 경우와 특정 음악적 요소를 알아볼 수 있게 사용한 경우를 구별한다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"음악 작품 참조","entry_url":"cards/ML-T02410/index.html"},{"id":"ML-T02411","row_version":2,"title":"철학 사상 참조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02405","tag_path":[],"summary":"철학자의 사상이나 개념, 논증 방식을 작품의 주제·인물·사건을 구성하는 데 반영한다. 작품에 적용할 때는 용어가 등장하는 것만으로 보지 말고, 해당 사상이 해석이나 전개에 실질적인 역할을 하는지 확인한다.","accent":"#7B876E","tab":"#A07A87","facet":"기원·전승·참조","bookmark":"철학 사상 참조","entry_url":"cards/ML-T02411/index.html"},{"id":"ML-T02412","row_version":2,"title":"대중문화·산업 맥락","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"작품이 만들어지고 유통되거나 소비되는 대중문화의 산업 구조와 관습을 배경으로 삼는다. 작품에 적용할 때는 배경에 산업이 등장하는 것과 제작·유통 방식이나 관습이 작품의 형식과 의미를 좌우하는 경우를 나눈다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"대중문화·산업 맥락","entry_url":"cards/ML-T02412/index.html"},{"id":"ML-T02413","row_version":2,"title":"한국 대중문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"한국의 대중문화 산업, 매체 관습, 유행과 사회적 맥락이 작품의 표현이나 제작 방식에 반영된다. 작품에 적용할 때는 한국어 사용이나 한국 배경만으로 판단하지 말고, 한국 대중문화의 구체적 관습이나 맥락이 작동하는지 본다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"한국 대중문화","entry_url":"cards/ML-T02413/index.html"},{"id":"ML-T02415","row_version":2,"title":"일본 대중문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"일본의 대중문화 산업과 장르 관습, 매체 형식, 유행이 작품의 표현이나 제작 방식에 반영된다. 작품에 적용할 때는 일본 배경이나 일본어 요소만으로 판단하지 말고, 일본 대중문화와의 구체적인 연관을 확인한다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"일본 대중문화","entry_url":"cards/ML-T02415/index.html"},{"id":"ML-T02416","row_version":2,"title":"할리우드 맥락","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"미국 할리우드의 영화 제작·배급 관행과 스타 시스템, 장르 문법 등이 작품의 형식이나 맥락에 작용한다. 작품에 적용할 때는 단순히 미국을 배경으로 하거나 영화적 연출을 쓴 경우와 할리우드 산업 관습을 참조한 경우를 구별한다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"할리우드 맥락","entry_url":"cards/ML-T02416/index.html"},{"id":"ML-T02417","row_version":2,"title":"영미 대중문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"영국·미국을 비롯한 영어권 대중문화의 작품, 매체 관습과 유행을 가리키거나 활용한다. 작품에 적용할 때는 영어 사용이나 서구권 배경만으로 묶지 말고, 영미권 문화와의 식별 가능한 연결이 있는지 살핀다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"영미 대중문화","entry_url":"cards/ML-T02417/index.html"},{"id":"ML-T02418","row_version":3,"title":"게임 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"게임의 제작·유통·플레이와 관련된 관습, 공동체 활동, 장르 인식이 작품에 반영되거나 소재가 된다. 작품에 적용할 때는 게임이 이야기 속에 등장하는 경우와 게임의 규칙·플레이 관습이 작품의 구성에 영향을 주는 경우를 구분한다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"게임 문화","entry_url":"cards/ML-T02418/index.html"},{"id":"ML-T02419","row_version":3,"title":"인터넷 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"온라인 플랫폼과 네트워크 공동체에서 생긴 밈, 표현 관습, 참여 방식이 작품에 반영된다. 작품에 적용할 때는 인터넷이나 기기가 등장하는 것과 특정 온라인 문화의 관습·표현을 작품이 활용하는 경우를 나눈다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"인터넷 문화","entry_url":"cards/ML-T02419/index.html"},{"id":"ML-T02420","row_version":3,"title":"동인 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02412","tag_path":[],"summary":"팬이 기존 작품을 바탕으로 창작물을 만들고 공유하며 교류하는 비공식 창작 공동체의 관습을 가리킨다. 작품에 적용할 때는 팬의 감상·소비 활동과 팬 창작·교류가 중심이 되는 활동을 구별한다.","accent":"#7B876E","tab":"#79866C","facet":"기원·전승·참조","bookmark":"동인 문화","entry_url":"cards/ML-T02420/index.html"},{"id":"ML-T02421","row_version":2,"title":"계보 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"group","parent_id":"ML-F29","tag_path":[],"summary":"작품·인물·관습 사이에 영향, 전승, 인용, 각색처럼 근거를 확인할 수 있는 연결이 성립하는 관계다. 작품에 적용할 때는 막연한 닮음만으로 계보를 설정하지 말고, 관계의 유형과 이를 뒷받침하는 자료를 특정한다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"계보 관계","entry_url":"cards/ML-T02421/index.html"},{"id":"ML-T02422","row_version":2,"title":"최초 확인 자료","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"특정 모티프나 관습이 확인되는 가장 이른 자료를 가리키며, 그 자료에서 무엇이 실제로 확인되는지 기록한다. 작품에 적용할 때는 발견된 자료 중 가장 오래된 것과 절대적인 최초 발생을 혼동하지 않는다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"최초 확인 자료","entry_url":"cards/ML-T02422/index.html"},{"id":"ML-T02423","row_version":2,"title":"오래된 선행 사례","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"현재의 사례보다 앞서 같은 모티프나 관습이 나타난 사례로, 유사성의 역사적 선례를 보여준다. 작품에 적용할 때는 선행 사례라는 이유만으로 직접 영향 관계를 주장하지 말고, 연결을 입증할 근거를 따로 확인한다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"오래된 선행 사례","entry_url":"cards/ML-T02423/index.html"},{"id":"ML-T02424","row_version":2,"title":"직접 인용 원전","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"작품이 문구, 장면, 이미지 또는 구조를 직접 가져온 원래 자료를 가리킨다. 작품에 적용할 때는 공통 주제나 유사한 표현만으로 직접 인용이라 하지 말고, 식별 가능한 차용 흔적을 확인한다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"직접 인용 원전","entry_url":"cards/ML-T02424/index.html"},{"id":"ML-T02425","row_version":4,"title":"각색 원전","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"새 작품이 서사, 인물, 설정 등을 바꾸어 다시 구성한 바탕 작품이나 자료를 뜻한다. 작품에 적용할 때는 재구성의 대상이 확인되는 경우에 한정하고, 영감이나 부분 인용과 구별한다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"각색 원전","entry_url":"cards/ML-T02425/index.html"},{"id":"ML-T02426","row_version":2,"title":"유사 전승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"서로 직접 이어졌다고 입증되지는 않았지만 비슷한 모티프나 이야기가 여러 전승에 나타나는 양상이다. 작품에 적용할 때는 유사성을 기록하되, 전파나 공통 원천을 확인된 사실처럼 단정하지 않는다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"유사 전승","entry_url":"cards/ML-T02426/index.html"},{"id":"ML-T02427","row_version":3,"title":"전파 경로","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"모티프나 작품이 매체·지역·공동체를 거치며 전달된 경로와 그 단계들을 가리킨다. 작품에 적용할 때는 가능한 이동 경로와 확인된 전달 기록을 구분하고, 각 단계의 시기와 매개를 근거에 맞춰 제시한다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"전파 경로","entry_url":"cards/ML-T02427/index.html"},{"id":"ML-T02428","row_version":2,"title":"지역적 변형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":"tag","parent_id":"ML-T02421","tag_path":[],"summary":"같은 모티프나 관습이 지역의 언어, 환경, 사회적 관습에 맞게 달라진 형태다. 작품에 적용할 때는 지역적 특징이 변형에 구체적으로 작용했는지 확인하고, 단지 배경 장소가 다른 경우와 구별한다.","accent":"#7B876E","tab":"#AF8665","facet":"기원·전승·참조","bookmark":"지역적 변형","entry_url":"cards/ML-T02428/index.html"},{"id":"ML-T02429","row_version":2,"title":"대상 연령","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"group","parent_id":"ML-F30","tag_path":[],"summary":"작품이 겨냥하거나 편하게 수용할 것으로 상정하는 연령 범위를 가리킨다. 실제 이용자의 나이와 작품의 공식 연령 등급은 별도로 확인한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"대상 연령","entry_url":"cards/ML-T02429/index.html"},{"id":"ML-T02430","row_version":2,"title":"유아 대상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02429","tag_path":[],"summary":"영유아의 언어·인지 발달과 짧은 주의 시간을 고려해 구성한 대상 설정이다. 단순한 그림이나 귀여운 표현만으로 분류하지 말고 이해 수준과 전달 방식을 살핀다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"유아 대상","entry_url":"cards/ML-T02430/index.html"},{"id":"ML-T02431","row_version":2,"title":"아동 대상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02429","tag_path":[],"summary":"대체로 아동기의 관심사와 이해 수준에 맞춰 내용과 표현을 구성한 대상 설정이다. 아동이 등장한다는 이유만으로 해당하지 않으며, 실제로 누구를 위한 작품인지 구분한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"아동 대상","entry_url":"cards/ML-T02431/index.html"},{"id":"ML-T02432","row_version":2,"title":"청소년 대상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02429","tag_path":[],"summary":"청소년기의 관심과 이해 수준을 주요 기준으로 삼아 구성한 대상 설정이다. 청소년 인물이 중심이라는 사실이나 일부 청소년 독자의 호응만으로 판단하지 않는다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"청소년 대상","entry_url":"cards/ML-T02432/index.html"},{"id":"ML-T02433","row_version":2,"title":"성인 대상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02429","tag_path":[],"summary":"성인의 관심사나 이해 수준을 주요 수용 대상으로 상정한 설정이다. 성적·폭력적 소재가 있거나 성인 인물이 등장한다는 사실만으로 분류하지 않는다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"성인 대상","entry_url":"cards/ML-T02433/index.html"},{"id":"ML-T02434","row_version":2,"title":"가족 대상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02429","tag_path":[],"summary":"연령대가 다른 가족 구성원이 함께 즐기거나 대화할 수 있도록 구성한 대상 설정이다. 단순히 어린이와 성인이 모두 볼 수 있다는 뜻과 가족 공동 감상 지향을 구별한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"가족 대상","entry_url":"cards/ML-T02434/index.html"},{"id":"ML-T02435","row_version":2,"title":"전 연령 지향","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02429","tag_path":[],"summary":"특정 연령층에 한정하지 않고 폭넓은 연령대의 접근성을 고려한 지향이다. 공식 등급이나 모든 사람에게 적합하다는 보장과 혼동하지 않는다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"전 연령 지향","entry_url":"cards/ML-T02435/index.html"},{"id":"ML-T02436","row_version":3,"title":"시장 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"group","parent_id":"ML-F30","tag_path":[],"summary":"출판·유통·홍보 관행에서 작품이 주로 겨냥하는 독자층을 가리킨다. 실제 독자의 성별이나 정체성을 단정하지 말고, 연령층·성별 구분과 시장상 포지셔닝을 구별한다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"시장 독자층","entry_url":"cards/ML-T02436/index.html"},{"id":"ML-T02437","row_version":2,"title":"소년 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02436","tag_path":[],"summary":"출판·유통 관행에서 주로 소년 독자를 겨냥하도록 설정한 시장 독자층이다. 실제 독자가 남성인지 여부나 작품 속 남성 인물의 비중으로 판단하지 않는다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"소년 독자층","entry_url":"cards/ML-T02437/index.html"},{"id":"ML-T02438","row_version":2,"title":"소녀 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02436","tag_path":[],"summary":"출판·유통 관행에서 주로 소녀 독자를 겨냥하도록 설정한 시장 독자층이다. 실제 독자의 성별을 단정하지 말고, 소녀 인물이 등장하는 작품과 구별한다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"소녀 독자층","entry_url":"cards/ML-T02438/index.html"},{"id":"ML-T02439","row_version":3,"title":"청년 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02436","tag_path":[],"summary":"청년층을 주요 시장 독자층으로 상정한 출판·유통상의 설정이다. 작품 속 인물의 나이나 청년 독자의 실제 독서 여부와는 별개로 다룬다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"청년 독자층","entry_url":"cards/ML-T02439/index.html"},{"id":"ML-T02440","row_version":3,"title":"여성 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02436","tag_path":[],"summary":"여성을 주요 시장 독자층으로 상정한 출판·유통상의 설정이다. 여성 독자의 실제 구성이나 작품의 여성 인물·주제를 근거 없이 추정하지 않는다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"여성 독자층","entry_url":"cards/ML-T02440/index.html"},{"id":"ML-T02441","row_version":3,"title":"남성 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02436","tag_path":[],"summary":"남성을 주요 시장 독자층으로 상정한 출판·유통상의 설정이다. 남성 독자의 실제 구성이나 작품의 남성 인물·주제와 동일시하지 않는다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"남성 독자층","entry_url":"cards/ML-T02441/index.html"},{"id":"ML-T02442","row_version":2,"title":"일반 독자층","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02436","tag_path":[],"summary":"특정 연령·성별 하위층에 한정하지 않고 폭넓은 독자층을 겨냥하는 시장 설정이다. 특정 독자층이 배제된다는 뜻으로 확대 해석하지 않는다.","accent":"#8B817D","tab":"#778F70","facet":"대상·수용맥락","bookmark":"일반 독자층","entry_url":"cards/ML-T02442/index.html"},{"id":"ML-T02443","row_version":2,"title":"이용 목적","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"group","parent_id":"ML-F30","tag_path":[],"summary":"사람이 작품이나 관련 활동을 이용하는 주된 동기와 용도를 가리킨다. 감상 장소나 참여 방식과 구별해, 무엇을 위해 이용하는지에 초점을 둔다.","accent":"#8B817D","tab":"#8B739C","facet":"대상·수용맥락","bookmark":"이용 목적","entry_url":"cards/ML-T02443/index.html"},{"id":"ML-T02444","row_version":3,"title":"오락 감상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02443","tag_path":[],"summary":"즐거움과 여가를 위해 작품을 보고 듣거나 플레이하는 이용 목적이다. 작품이 오락적 요소를 포함한다는 사실과 이용자의 주된 목적을 구분한다.","accent":"#8B817D","tab":"#8B739C","facet":"대상·수용맥락","bookmark":"오락 감상","entry_url":"cards/ML-T02444/index.html"},{"id":"ML-T02445","row_version":2,"title":"학습·교육","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02443","tag_path":[],"summary":"지식·기술·태도의 습득이나 교육을 위해 작품을 활용하는 목적이다. 배울 거리가 등장하는 것만으로는 충분하지 않으며 학습에 쓰이는 맥락을 확인한다.","accent":"#8B817D","tab":"#8B739C","facet":"대상·수용맥락","bookmark":"학습·교육","entry_url":"cards/ML-T02445/index.html"},{"id":"ML-T02446","row_version":2,"title":"창작 참고","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02443","tag_path":[],"summary":"새로운 창작물을 구상하거나 제작할 때 아이디어와 표현 방식을 살펴보는 이용 목적이다. 작품을 즐겨 감상하는 일이나 그 작품을 그대로 모방하는 일과 구별한다.","accent":"#8B817D","tab":"#8B739C","facet":"대상·수용맥락","bookmark":"창작 참고","entry_url":"cards/ML-T02446/index.html"},{"id":"ML-T02447","row_version":2,"title":"비평·연구","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02443","tag_path":[],"summary":"작품의 형식·의미·맥락을 분석하거나 지식을 축적하기 위해 이용하는 목적이다. 감상 후 의견을 나누는 행위와 체계적인 비평·연구 활동을 구별한다.","accent":"#8B817D","tab":"#8B739C","facet":"대상·수용맥락","bookmark":"비평·연구","entry_url":"cards/ML-T02447/index.html"},{"id":"ML-T02448","row_version":2,"title":"공동체 활동","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":"tag","parent_id":"ML-T02443","tag_path":[],"summary":"공통 관심사를 바탕으로 다른 사람들과 교류하고 활동하기 위해 작품을 이용하는 목적이다. 단순히 여러 사람이 함께 보는 상황보다 지속적 교류나 공동 활동의 맥락을 본다.","accent":"#8B817D","tab":"#8B739C","facet":"대상·수용맥락","bookmark":"공동체 활동","entry_url":"cards/ML-T02448/index.html"}]}.cards;